        raise APIError(409, "vector_index_state_invalid", "Vector index state is invalid; re-index storage is required")

def active_generation(self) -> str:
    """Return the validated generation named by the managed active pointer."""
    if not self.managed:
        raise VectorIndexStateError("Active generation requires a managed vector index")
    self._ready()
    return str(self._read_pointer()["generation"])

def _vector_set_hash(vectors: dict[str, Sequence[float]]) -> str:
    digest = hashlib.sha256()
    for chunk_id in sorted(vectors):
        digest.update(chunk_id.encode("ascii"))
        digest.update(b"\0")
        digest.update(struct.pack(f"<{len(vectors[chunk_id])}f", *vectors[chunk_id]))
    return digest.hexdigest()

