        raise self._error("InvalidResponse", "Ollama generated text must not be empty")
    return text

def test_openai_compatible_llm_preserves_finish_reason(monkeypatch) -> None:
    install_response(
        monkeypatch,
        {
            "model": "chat-served",
            "choices": [
                {"finish_reason": "stop", "message": {"content": "grounded answer"}}
            ],
        },
    )

    result = OpenAICompatibleLLMProvider(
        "chat-requested", "https://compatible.example/v1"
    ).generate(LLMRequest("Question"))

    assert result.finish_reason == "stop"

def respond(request, timeout):
    captured.append((request, timeout))
    return FakeHTTPResponse(payload)

def install_response(monkeypatch, payload):
    captured = []

    def respond(request, timeout):
        captured.append((request, timeout))
        return FakeHTTPResponse(payload)

    monkeypatch.setattr("urllib.request.urlopen", respond)
    return captured

def test_openai_compatible_llm_maps_json_response_format(monkeypatch) -> None:
    captured = install_response(
        monkeypatch,
        {"choices": [{"message": {"content": "{}"}}]},
    )

    OpenAICompatibleLLMProvider("chat", "https://compatible.example/v1").generate(
        LLMRequest("Question", response_format="json")
    )

    assert json.loads(captured[0][0].data) == {
        "model": "chat",
        "messages": [{"role": "user", "content": "Question"}],
        "temperature": 0.0,
        "response_format": {"type": "json_object"},
    }

def generate(self, request: LLMRequest) -> LLMResponse:
    self.requests.append(request)
    if self.error:
        raise self.error
    text = self.texts[min(len(self.requests) - 1, len(self.texts) - 1)] if self.texts else self.text
    return LLMResponse(
        text,
        "fake-model",
        "fake-provider",
        finish_reason=self.finish_reason,
    )

def _response(self, response: dict[str, Any]) -> tuple[str, str | None]:
    choices = response.get("choices")
    if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
        raise self._error(
            "invalid_response_choices", "OpenAI-compatible response missing choices"
        )
    choice = choices[0]
    message = choice.get("message")
    if not isinstance(message, dict):
        raise self._error(
            "invalid_response_message", "OpenAI-compatible response missing message"
        )
    text = message.get("content")
    if not isinstance(text, str):
        raise self._error(
            "invalid_response_content", "OpenAI-compatible response missing message content"
        )
    if not text.strip():
        raise self._error(
            "invalid_response_empty_content",
            "OpenAI-compatible generated text must not be empty",
        )
    finish_reason = choice.get("finish_reason")
    return text, finish_reason if isinstance(finish_reason, str) else None

